/* Camps own spawn/respawn state; individual monsters share the combat and terrain resolvers. */
window.createJungleV14=function(env,m){const C=GAME_CONFIG,defs=new Map(MONSTERS_V14.map(x=>[x.id,x])),now=env.time,units=env.units;let camps=new Map,dragons=0,sequence=0;
function monsterLevel(){return Math.max(1,Math.min(12,1+Math.floor(now()/180)))}
function legal(p,r){return C.map.nearestLegal?.(p,r)||p}function spawn(id,p,camp,extra={}){let d=defs.get(id),q=legal(p,d.radius);if(!q||env.blocked(q.x,q.y,d.radius))throw Error('Illegal monster spawn '+id);// V18 野怪成长：每 3 分钟提升 1 级（上限 12 级），生命 +7%/级、攻击 +5%/级；召唤物和河道生物不成长。
let level=extra.summoned||id==='RIFT_SCUTTLER'?1:monsterLevel(),hp=Math.round(d.hp*(1+.07*(level-1))),attack=d.attack*(1+.05*(level-1));let u={...d,...q,hp,attack,monsterLevel:level,type:'monster',monsterId:id,id:env.nextId(),kind:id==='BLUE_SENTINEL'?'blue':id==='RED_BRAMBLEBACK'?'red':id,team:2,lane:1,home:{...q},maxHp:hp,attackCd:0,death:0,respawn:Infinity,angle:0,visualScale:1,campId:camp.campId,epic:['史诗','巨龙'].includes(d.category),abilityNext:now()+d.abilityCooldown,monsterAnimation:'idle',monsterBornAt:now(),...extra};units().push(u);return u}
function types(c){if(c.kind==='void'){if(now()>=1200)return['BARON_NASHOR'];if(now()>=840)return['RIFT_HERALD'];return['VOIDGRUB','VOIDGRUB','VOIDGRUB']}if(c.kind==='colossus')return['RIFT_COLOSSUS'];if(c.kind==='dragon')return[dragons>=4?'ELDER_DRAGON':['INFERNAL_DRAKE','MOUNTAIN_DRAKE','OCEAN_DRAKE','CLOUD_DRAKE','HEXTECH_DRAKE','CHEMTECH_DRAKE'][dragons%6]];return c.monsterPositions.map(p=>p.type)}
function spawnCamp(c){if(c.kind==='colossus'&&c.sites){let s=c.sites[(c.siteIndex||0)%c.sites.length];c.x=s.x;c.y=s.y;c.spawnPosition={...s};env.toast?.('渊核巨像在'+((c.siteIndex||0)%2?'下':'上')+'半区河道祭坛苏醒')}let t=types(c);for(let [i,id]of t.entries()){let p=c.monsterPositions[i]||{x:c.x+Math.cos(i*2.1)*i*120,y:c.y+Math.sin(i*2.1)*i*120};spawn(id,p,c)}c.alive=true;c.spawnedAt=now()}
function reset(){camps.clear();dragons=0;sequence=0;if(C.gameModeId!=='SR')return;for(let c of C.map.camps||[])camps.set(c.campId,{...c,nextSpawn:c.firstSpawn,alive:false})}
function onDeath(u,source){if(!u.monsterId)return;u.monsterDeathAt=now();u.monsterAnimation='death';u.death=Infinity;let c=camps.get(u.campId);if(!c)return;if(u.monsterId==='ANCIENT_KRUG')for(let sign of [-1,1])spawn('KRUG',{x:u.x+sign*65,y:u.y+40},c);if(u.monsterId==='KRUG')for(let sign of [-1,1])spawn('MINI_KRUG',{x:u.x+sign*45,y:u.y+35},c);if(c.kind==='dragon'){dragons++;if(source?.team<2)for(let h of units().filter(v=>v.type==='hero'&&v.team===source.team)){h.dragonStacks=(h.dragonStacks||0)+1;h.dragonBuffUntil=now()+120}if(dragons===3&&window.ElementalTerrainManager)ElementalTerrainManager.apply(u.monsterId.split('_')[0]);}if(u.monsterId==='RIFT_COLOSSUS'){c.siteIndex=(c.siteIndex||0)+1;for(let v of units())if(v.monsterId==='RIFT_SHARD'&&v.campId===c.campId&&v.hp>0){v.hp=0;v.monsterDeathAt=now();v.death=Infinity}if(source?.team<2){for(let h of units().filter(v=>v.type==='hero'&&v.team===source.team))h.colossusBuffUntil=now()+150;env.toast?.('我方获得「渊核庇护」：受到伤害 -12%，攻城 +25%（150 秒）',source.team);env.toast?.('敌方获得了「渊核庇护」',1-source.team)}}
 if(u.monsterId==='BARON_NASHOR'&&source?.team<2)for(let h of units().filter(v=>v.type==='hero'&&v.team===source.team))h.baronBuffUntil=now()+180;
 if(!units().some(v=>v!==u&&v.campId===u.campId&&v.hp>0)){c.alive=false;c.nextSpawn=now()+c.respawnTime;if(c.kind==='void'&&now()<840)c.nextSpawn=840;}}
function tick(dt){if(C.gameModeId!=='SR')return;for(let c of camps.values())if(c.alive&&!units().some(u=>u.campId===c.campId&&u.hp>0)){c.alive=false;c.nextSpawn=Math.max(now()+c.respawnTime,c.kind==='void'&&now()<840?840:0);}for(let c of camps.values())if(!c.alive&&now()>=c.nextSpawn)spawnCamp(c);for(let u of units()){if(!u.monsterId||!(u.hp>0)||m.temporal.isFrozen(u))continue;let t=u.lastAttacker;if(t&&(!(t.hp>0)||Math.hypot(t.x-u.home.x,t.y-u.home.y)>u.leash))u.lastAttacker=null;if(!u.lastAttacker){let target=m.nearest(u,u.aggroRange,t=>t.type==='hero'&&t.team<2&&t.hp>0&&C.map.lineOfSight(u,t));if(target)u.lastAttacker=target}t=u.lastAttacker;u.monsterAnimation=t?'attack':Math.hypot(u.x-u.home.x,u.y-u.home.y)>10?'move':'idle';if(t&&u.ability&&u.abilityNext<=now()){u.abilityNext=now()+u.abilityCooldown;u.monsterAbility={start:now(),at:now()+.65,until:now()+1.1,x:t.x,y:t.y,radius:u.abilityRadius};env.ring(t.x,t.y,u.abilityRadius,u.color,.65)}// V18 渊核巨像二阶段：生命低于 50% 时召唤 2 个碎晶，技能冷却缩短 40%，砸地附带自身周围脉冲。
if(u.monsterId==='RIFT_COLOSSUS'&&!u.phase2&&u.hp<u.maxHp*.5){u.phase2=true;u.abilityCooldown*=.6;let c=camps.get(u.campId);for(let i=0;i<2;i++)spawn('RIFT_SHARD',{x:u.x+Math.cos(i*Math.PI+.6)*260,y:u.y+Math.sin(i*Math.PI+.6)*260},c||{campId:u.campId},{expires:now()+25,summoned:true});env.ring(u.x,u.y,u.radius+260,'#7ef2e2',.8)}
let a=u.monsterAbility;if(a&&!a.applied&&a.at<=now()){a.applied=true;if(u.ability==='VOID_SWARM'){let c=camps.get(u.campId);for(let i=0;i<3;i++)spawn('VOIDMITE',{x:u.x+Math.cos(i*2.1)*100,y:u.y+Math.sin(i*2.1)*100},c,{expires:now()+12,summoned:true})}else for(let v of m.nearby(a,a.radius,v=>v.team<2&&v.hp>0&&['hero','minion'].includes(v.type)))m.deal(v,u.abilityDamage,u,u.ability==='RIFT_CHARGE'?'physical':'magic',{abilityId:u.ability});if(u.ability==='ABYSS_SLAM'&&u.phase2)for(let v of m.nearby(u,u.radius+260,v=>v.team<2&&v.hp>0&&['hero','minion'].includes(v.type)))m.deal(v,u.abilityDamage*.5,u,'magic',{abilityId:'ABYSS_PULSE'});if(u.ability==='RIFT_CHARGE'&&t)m.core.startDisplacement(u,{x:t.x,y:t.y},{type:'DASH',duration:.4,source:u})}if(u.expires<=now()){u.hp=0;u.monsterDeathAt=now();u.death=Infinity}}
}
return{reset,tick,onDeath,spawn,definitions:defs,camps:()=>[...camps.values()],exportState:()=>({camps:[...camps],dragons,sequence}),restore(s){camps=new Map(s?.camps||[]);dragons=s?.dragons||0;sequence=s?.sequence||0}};
};
